1	package nettrace
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"sync"
9		"syscall"
10		"time"
11	)
12	
13	// prober opens one probe connection per TTL. The system implementation lives
14	// in the platform files; the tests drive run with a fake.
15	type prober interface {
16		// open returns a connection whose probes leave with the given TTL.
17		open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error)
18	}
19	
20	// probeConn sends one probe and waits for what answers it.
21	type probeConn interface {
22		// send emits the probe and returns the time it left.
23		send() (time.Time, error)
24		// await waits for the answer until the given time. It returns errSilent
25		// when nothing came back by then, and ctx.Err() when ctx ended first.
26		await(ctx context.Context, until time.Time) (reply, error)
27		close() error
28	}
29	
30	// errSilent is await's answer when nothing came back before its deadline.
31	var errSilent = errors.New("no answer before the probe timeout")
32	
33	// probeResult is what one TTL's goroutine hands back. resolved is false when
34	// the probe was cut short (cancellation, deadline, upper TTL no longer needed).
35	type probeResult struct {
36		ttl      int
37		hop      Hop
38		resolved bool
39	}
40	
41	// run traces the path with p. Every connection is opened first, in the
42	// caller's goroutine, so that a failing open stops everything before any
43	// probe is sent; then one goroutine per TTL sends and awaits in parallel.
44	func run(ctx context.Context, target netip.Addr, opts Options, p prober) (Result, error) {
45		opts = opts.Normalized()
46		start := time.Now()
47		runCtx, cancel := context.WithTimeout(ctx, opts.Deadline)
48		defer cancel()
49	
50		conns, err := openAll(runCtx, p, target, opts.MaxHops)
51		if err != nil {
52			if runCtx.Err() != nil {
53				return endedEarly(runCtx, target, nil, opts.MaxHops, start), nil
54			}
55			return Result{}, openError(err)
56		}
57		return probeAll(runCtx, target, opts, conns, start), nil
58	}
59	
60	// openAll opens one connection per TTL, 1 to n. On failure it closes the ones
61	// already open and returns the error.
62	func openAll(ctx context.Context, p prober, target netip.Addr, n int) ([]probeConn, error) {
63		conns := make([]probeConn, 0, n)
64		for ttl := 1; ttl <= n; ttl++ {
65			if err := ctx.Err(); err != nil {
66				closeAll(conns)
67				return nil, err
68			}
69			c, err := p.open(ctx, target, ttl)
70			if err != nil {
71				closeAll(conns)
72				return nil, err
73			}
74			conns = append(conns, c)
75		}
76		return conns, nil
77	}
78	
79	func closeAll(conns []probeConn) {
80		for _, c := range conns {
81			_ = c.close()
82		}
83	}
84	
85	// openError turns "the kernel refuses this socket option or socket" into
86	// ErrUnsupported, keeping the raw error for the message. Anything else is
87	// returned as is.
88	func openError(err error) error {
89		for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP, syscall.EPERM, syscall.EACCES} {
90			if errors.Is(err, errno) {
91				return fmt.Errorf("%w: %w", ErrUnsupported, err)
92			}
93		}
94		return err
95	}
96	
97	// probeAll runs phase 2: one goroutine per connection.
98	func probeAll(ctx context.Context, target netip.Addr, opts Options, conns []probeConn, start time.Time) Result {
99		n := len(conns)
100		results := make(chan probeResult, n)
101		cancels := make([]context.CancelFunc, n+1) // indexed by TTL
102		var wg sync.WaitGroup
103		for i, c := range conns {
104			ttl := i + 1
105			var tctx context.Context
106			tctx, cancels[ttl] = context.WithCancel(ctx)
107			wg.Add(1)
108			go func() {
109				defer wg.Done()
110				defer func() { _ = c.close() }()
111				results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
112			}()
113		}
114	
115		t := newTally(n)
116		cutAbove := func() {
117			if term := t.terminal(); term > 0 {
118				for ttl := term + 1; ttl <= n; ttl++ {
119					cancels[ttl]()
120				}
121			}
122		}
123	collect:
124		for !t.complete() {
125			select {
126			case r := <-results:
127				t.add(r)
128				cutAbove()
129			case <-ctx.Done():
130				break collect
131			}
132		}
133		for _, cancel := range cancels[1:] {
134			cancel()
135		}
136		wg.Wait()
137		close(results)
138		for r := range results { // answers that landed while stopping
139			t.add(r)
140		}
141	
142		if t.complete() {
143			return t.result(target, start)
144		}
145		return endedEarly(ctx, target, t, n, start)
146	}
147	
148	// probeOne sends the probe for one TTL and turns what comes back into a Hop.
149	func probeOne(ctx context.Context, c probeConn, ttl int, target netip.Addr, timeout time.Duration) probeResult {
150		sentAt, err := c.send()
151		if err != nil {
152			if ctx.Err() != nil {
153				return probeResult{ttl: ttl}
154			}
155			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
156		}
157		rep, err := c.await(ctx, sentAt.Add(timeout))
158		recvAt := time.Now()
159		switch {
160		case err != nil && ctx.Err() != nil:
161			return probeResult{ttl: ttl}
162		case errors.Is(err, errSilent):
163			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopSilent}, resolved: true}
164		case err != nil:
165			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
166		}
167		rtt := rep.RTT
168		if rtt == 0 {
169			rtt = recvAt.Sub(sentAt)
170		}
171		hop := Hop{TTL: ttl, Kind: classify(rep, target), Addr: rep.Addr, RTT: rtt, ICMPType: rep.ICMPType, ICMPCode: rep.ICMPCode}
172		return probeResult{ttl: ttl, hop: hop, resolved: true}
173	}
174	
175	// tally collects the resolved hops of a run.
176	type tally struct {
177		hops []probeResult // indexed by TTL, index 0 unused
178	}
179	
180	func newTally(n int) *tally { return &tally{hops: make([]probeResult, n+1)} }
181	
182	func (t *tally) add(r probeResult) {
183		if r.resolved {
184			t.hops[r.ttl] = r
185		}
186	}
187	
188	// terminal returns the smallest TTL that reached or was refused, or 0.
189	func (t *tally) terminal() int {
190		for ttl := 1; ttl < len(t.hops); ttl++ {
191			if r := t.hops[ttl]; r.resolved && (r.hop.Kind == HopTarget || r.hop.Kind == HopUnreachable) {
192				return ttl
193			}
194		}
195		return 0
196	}
197	
198	// complete reports whether the trace can end: every TTL up to the terminal
199	// one (or every TTL when there is none) is resolved.
200	func (t *tally) complete() bool {
201		limit := len(t.hops) - 1
202		if term := t.terminal(); term > 0 {
203			limit = term
204		}
205		for ttl := 1; ttl <= limit; ttl++ {
206			if !t.hops[ttl].resolved {
207				return false
208			}
209		}
210		return true
211	}
212	
213	// result builds the Result of a complete tally.
214	func (t *tally) result(target netip.Addr, start time.Time) Result {
215		last, outcome := len(t.hops)-1, OutcomeMaxHops
216		if term := t.terminal(); term > 0 {
217			last = term
218			outcome = OutcomeReached
219			if t.hops[term].hop.Kind == HopUnreachable {
220				outcome = OutcomeUnreachable
221			}
222		}
223		hops := make([]Hop, 0, last)
224		for ttl := 1; ttl <= last; ttl++ {
225			hops = append(hops, t.hops[ttl].hop)
226		}
227		return Result{Target: target, Outcome: outcome, Hops: hops, Duration: time.Since(start)}
228	}
229	
230	// endedEarly builds the Result of a run that ctx cut short. A deadline lists
231	// every TTL, the unanswered ones as HopUnresolved; a cancellation keeps only
232	// the hops that were resolved. t is nil when nothing was probed yet.
233	func endedEarly(ctx context.Context, target netip.Addr, t *tally, n int, start time.Time) Result {
234		res := Result{Target: target, Outcome: OutcomeCancelled, Duration: time.Since(start)}
235		deadline := errors.Is(ctx.Err(), context.DeadlineExceeded)
236		if deadline {
237			res.Outcome = OutcomeDeadline
238		}
239		if t == nil {
240			return res
241		}
242		for ttl := 1; ttl <= n; ttl++ {
243			switch r := t.hops[ttl]; {
244			case r.resolved:
245				res.Hops = append(res.Hops, r.hop)
246			case deadline:
247				res.Hops = append(res.Hops, Hop{TTL: ttl, Kind: HopUnresolved})
248			}
249		}
250		return res
251	}
