1	package nettrace
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"runtime"
9		"sync"
10		"sync/atomic"
11		"syscall"
12		"testing"
13		"time"
14	)
15	
16	// The engine tests run on every platform: they drive run() with a fake prober
17	// and real (short) time, never a socket.
18	
19	var engineTarget = netip.MustParseAddr("192.0.2.99")
20	
21	// probeSpec scripts what one TTL's connection does.
22	type probeSpec struct {
23		openErr   error         // open fails with this error
24		openBlock bool          // open blocks until ctx is done, then returns ctx.Err()
25		sendErr   error         // send fails with this error
26		sendDelay time.Duration // send takes this long
27		delay     time.Duration // the answer arrives this long after the send
28		rep       *reply        // the answer; with awaitErr nil too, the probe is silent
29		awaitErr  error         // await fails with this error after delay
30		// ignoreUntil models a probe that nothing but the trace's own deadline or
31		// a cancellation can end: await does not honor its until argument.
32		ignoreUntil bool
33	}
34	
35	type fakeProber struct {
36		spec func(ttl int) probeSpec
37		n    int // MaxHops of the run: every open must succeed before any send
38	
39		attempts, openOK, closes, sends, awaits atomic.Int32
40	
41		onOpen, onSend, onAwait func(ttl int)
42	
43		// barrier: await blocks until barrierN probes are waiting at once.
44		barrierN        int
45		barrierCh       chan struct{}
46		waiting         atomic.Int32
47		barrierTimeouts atomic.Int32
48	
49		mu         sync.Mutex
50		violations []string
51	}
52	
53	func newFake(n int, spec func(ttl int) probeSpec) *fakeProber {
54		return &fakeProber{spec: spec, n: n}
55	}
56	
57	func (p *fakeProber) violate(format string, args ...any) {
58		p.mu.Lock()
59		defer p.mu.Unlock()
60		p.violations = append(p.violations, fmt.Sprintf(format, args...))
61	}
62	
63	func (p *fakeProber) withBarrier(n int) *fakeProber {
64		p.barrierN = n
65		p.barrierCh = make(chan struct{})
66		return p
67	}
68	
69	func (p *fakeProber) open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error) {
70		p.attempts.Add(1)
71		if dst != engineTarget {
72			p.violate("open for %v, want %v", dst, engineTarget)
73		}
74		if p.onOpen != nil {
75			p.onOpen(ttl)
76		}
77		s := p.spec(ttl)
78		if s.openBlock {
79			<-ctx.Done()
80			return nil, ctx.Err()
81		}
82		if s.openErr != nil {
83			return nil, s.openErr
84		}
85		p.openOK.Add(1)
86		return &fakeConn{p: p, ttl: ttl, spec: s}, nil
87	}
88	
89	type fakeConn struct {
90		p      *fakeProber
91		ttl    int
92		spec   probeSpec
93		sentAt time.Time
94		closed atomic.Bool
95	}
96	
97	func (c *fakeConn) send() (time.Time, error) {
98		p := c.p
99		p.sends.Add(1)
100		if got := int(p.openOK.Load()); got != p.n {
101			p.violate("TTL %d sent with only %d/%d connections open", c.ttl, got, p.n)
102		}
103		if p.onSend != nil {
104			p.onSend(c.ttl)
105		}
106		if c.spec.sendDelay > 0 {
107			time.Sleep(c.spec.sendDelay)
108		}
109		if c.spec.sendErr != nil {
110			return time.Time{}, c.spec.sendErr
111		}
112		c.sentAt = time.Now()
113		return c.sentAt, nil
114	}
115	
116	func (c *fakeConn) await(ctx context.Context, until time.Time) (reply, error) {
117		p := c.p
118		p.awaits.Add(1)
119		if p.onAwait != nil {
120			p.onAwait(c.ttl)
121		}
122		if p.barrierCh != nil {
123			if int(p.waiting.Add(1)) == p.barrierN {
124				close(p.barrierCh)
125			}
126			select {
127			case <-p.barrierCh:
128			case <-ctx.Done():
129				return reply{}, ctx.Err()
130			case <-time.After(2 * time.Second):
131				p.barrierTimeouts.Add(1)
132				return reply{}, errors.New("fake: barrier timeout, probes are not in flight together")
133			}
134		}
135		if err := ctx.Err(); err != nil {
136			return reply{}, err
137		}
138		s := c.spec
139		answers := s.rep != nil || s.awaitErr != nil
140		replyAt := c.sentAt.Add(s.delay)
141		var fire time.Time
142		silent := false
143		switch {
144		case !answers && s.ignoreUntil:
145			<-ctx.Done()
146			return reply{}, ctx.Err()
147		case !answers || (!s.ignoreUntil && replyAt.After(until)):
148			fire, silent = until, true
149		default:
150			fire = replyAt
151		}
152		t := time.NewTimer(time.Until(fire))
153		defer t.Stop()
154		select {
155		case <-ctx.Done():
156			return reply{}, ctx.Err()
157		case <-t.C:
158		}
159		if silent {
160			if err := ctx.Err(); err != nil {
161				return reply{}, err
162			}
163			return reply{}, errSilent
164		}
165		if s.awaitErr != nil {
166			return reply{}, s.awaitErr
167		}
168		return *s.rep, nil
169	}
170	
171	func (c *fakeConn) close() error {
172		if c.closed.Swap(true) {
173			c.p.violate("TTL %d closed twice", c.ttl)
174		}
175		c.p.closes.Add(1)
176		return nil
177	}
178	
179	// assertBalanced checks the invariants every run must keep, whatever happened.
180	func assertBalanced(t *testing.T, p *fakeProber) {
181		t.Helper()
182		if o, c := p.openOK.Load(), p.closes.Load(); o != c {
183			t.Errorf("opened %d connections but closed %d", o, c)
184		}
185		p.mu.Lock()
186		defer p.mu.Unlock()
187		for _, v := range p.violations {
188			t.Error(v)
189		}
190	}
191	
192	func routerReply(addr string) *reply {
193		return &reply{Addr: netip.MustParseAddr(addr), ICMPType: icmpTimeExceeded, Origin: originICMP}
194	}
195	
196	func targetReply() *reply {
197		return &reply{Addr: engineTarget, ICMPType: icmpDestUnreachable, ICMPCode: icmpCodePortUnreach, Origin: originICMP}
198	}
199	
200	func unreachReply(addr string, code uint8) *reply {
201		return &reply{Addr: netip.MustParseAddr(addr), ICMPType: icmpDestUnreachable, ICMPCode: code, Origin: originICMP}
202	}
203	
204	// table builds a spec function from per-TTL specs, with a default for the rest.
205	func table(def probeSpec, m map[int]probeSpec) func(int) probeSpec {
206		return func(ttl int) probeSpec {
207			if s, ok := m[ttl]; ok {
208				return s
209			}
210			return def
211		}
212	}
213	
214	type runOut struct {
215		res Result
216		err error
217	}
