219	// runBG starts run and returns a channel for its result.
220	func runBG(ctx context.Context, opts Options, p prober) <-chan runOut {
221		ch := make(chan runOut, 1)
222		go func() {
223			res, err := run(ctx, engineTarget, opts, p)
224			ch <- runOut{res, err}
225		}()
226		return ch
227	}
228	
229	func waitRun(t *testing.T, ch <-chan runOut) runOut {
230		t.Helper()
231		select {
232		case out := <-ch:
233			return out
234		case <-time.After(5 * time.Second):
235			t.Fatal("run did not return within 5s")
236			return runOut{}
237		}
238	}
