240	func mustRun(t *testing.T, ctx context.Context, opts Options, p prober) Result {
241		t.Helper()
242		res, err := run(ctx, engineTarget, opts, p)
243		if err != nil {
244			t.Fatalf("run: unexpected error %v", err)
245		}
246		if res.Target != engineTarget {
247			t.Errorf("Result.Target = %v, want %v", res.Target, engineTarget)
248		}
249		return res
250	}
