252	// Criterion 1: hops in order, address, RTT, list cut at the target.
253	func TestRunReachesTargetAndCutsTheList(t *testing.T) {
254		silentForever := probeSpec{ignoreUntil: true}
255		fp := newFake(8, table(silentForever, map[int]probeSpec{
256			1: {rep: routerReply("10.0.0.1"), delay: 10 * time.Millisecond},
257			2: {rep: routerReply("10.0.0.2"), delay: 20 * time.Millisecond},
258			3: {rep: routerReply("10.0.0.3"), delay: 30 * time.Millisecond},
259			4: {rep: targetReply(), delay: 40 * time.Millisecond},
260			// TTL 5..8 never answer: they must be canceled, not waited for.
261		}))
262		start := time.Now()
263		res := mustRun(t, context.Background(), Options{MaxHops: 8, ProbeTimeout: 5 * time.Second}, fp)
264		elapsed := time.Since(start)
265	
266		if res.Outcome != OutcomeReached {
267			t.Fatalf("Outcome = %v, want reached", res.Outcome)
268		}
269		if len(res.Hops) != 4 {
270			t.Fatalf("len(Hops) = %d, want 4 (cut at the target): %+v", len(res.Hops), res.Hops)
271		}
272		want := []struct {
273			kind  HopKind
274			addr  string
275			delay time.Duration
276		}{
277			{HopRouter, "10.0.0.1", 10 * time.Millisecond},
278			{HopRouter, "10.0.0.2", 20 * time.Millisecond},
279			{HopRouter, "10.0.0.3", 30 * time.Millisecond},
280			{HopTarget, engineTarget.String(), 40 * time.Millisecond},
281		}
282		for i, w := range want {
283			h := res.Hops[i]
284			if h.TTL != i+1 {
285				t.Errorf("Hops[%d].TTL = %d, want %d", i, h.TTL, i+1)
286			}
287			if h.Kind != w.kind {
288				t.Errorf("Hops[%d].Kind = %v, want %v", i, h.Kind, w.kind)
289			}
290			if h.Addr != netip.MustParseAddr(w.addr) {
291				t.Errorf("Hops[%d].Addr = %v, want %s", i, h.Addr, w.addr)
292			}
293			if h.RTT < w.delay || h.RTT > w.delay+200*time.Millisecond {
294				t.Errorf("Hops[%d].RTT = %v, want within [%v, %v]", i, h.RTT, w.delay, w.delay+200*time.Millisecond)
295			}
296		}
297		if elapsed > time.Second {
298			t.Errorf("run took %v: the probes above the target were waited for", elapsed)
299		}
300		if res.Duration <= 0 || res.Duration > elapsed+50*time.Millisecond {
301			t.Errorf("Duration = %v, want in (0, %v]", res.Duration, elapsed)
302		}
303		if got := fp.openOK.Load(); got != 8 {
304			t.Errorf("opened %d connections, want 8 (one per TTL)", got)
305		}
306		assertBalanced(t, fp)
307	}
