489	// Criterion 4: no goroutine survives a canceled run, over many cycles of every
490	// phase, and every opened connection is closed.
491	func TestRunCancelLeavesNoGoroutine(t *testing.T) {
492		before := runtime.NumGoroutine()
493		for i := 0; i < 100; i++ {
494			ctx, cancel := context.WithCancel(context.Background())
495			var fp *fakeProber
496			switch i % 3 {
497			case 0: // cancel while probes await
498				fp = newFake(4, table(probeSpec{ignoreUntil: true}, nil))
499				var once sync.Once
500				fp.onAwait = func(int) { once.Do(cancel) }
501			case 1: // cancel while open blocks
502				fp = newFake(4, table(probeSpec{}, map[int]probeSpec{3: {openBlock: true}}))
503				fp.onOpen = func(ttl int) {
504					if ttl == 3 {
505						cancel()
506					}
507				}
508			default: // cancel while a send is running
509				fp = newFake(4, table(probeSpec{sendDelay: 5 * time.Millisecond, ignoreUntil: true}, nil))
510				var once sync.Once
511				fp.onSend = func(int) { once.Do(cancel) }
512			}
513			out := waitRun(t, runBG(ctx, Options{MaxHops: 4, ProbeTimeout: 10 * time.Second}, fp))
514			cancel()
515			if out.err != nil || out.res.Outcome != OutcomeCancelled {
516				t.Fatalf("cycle %d: got (%v, %v), want (canceled, nil)", i, out.res.Outcome, out.err)
517			}
518			if o, c := fp.openOK.Load(), fp.closes.Load(); o != c {
519				t.Fatalf("cycle %d: opened %d, closed %d", i, o, c)
520			}
521		}
522		deadline := time.Now().Add(2 * time.Second)
523		for runtime.NumGoroutine() > before && time.Now().Before(deadline) {
524			time.Sleep(5 * time.Millisecond)
525		}
526		if after := runtime.NumGoroutine(); after > before {
527			t.Errorf("goroutines: %d before, %d after 100 canceled runs", before, after)
528		}
529	}
