576	// Criterion 7: an open that fails stops everything before any probe is sent.
577	func TestRunOpenFailure(t *testing.T) {
578		routeErr := fmt.Errorf("connect: %w", ErrNoRoute)
579		tests := []struct {
580			name     string
581			failAt   int
582			err      error
583			wantIs   []error
584			wantNot  []error
585			wantOpen int32 // connections that did open before the failure
586		}{
587			{
588				name:     "option not supported at TTL 7 becomes ErrUnsupported",
589				failAt:   7,
590				err:      fmt.Errorf("setsockopt IP_RECVERR: %w", syscall.ENOPROTOOPT),
591				wantIs:   []error{ErrUnsupported, syscall.ENOPROTOOPT},
592				wantOpen: 6,
593			},
594			{
595				name:     "any other open error comes back as is",
596				failAt:   5,
597				err:      routeErr,
598				wantIs:   []error{ErrNoRoute},
599				wantNot:  []error{ErrUnsupported},
600				wantOpen: 4,
601			},
602		}
603		for _, tc := range tests {
604			t.Run(tc.name, func(t *testing.T) {
605				fp := newFake(10, table(probeSpec{}, map[int]probeSpec{tc.failAt: {openErr: tc.err}}))
606				res, err := run(context.Background(), engineTarget, Options{MaxHops: 10, ProbeTimeout: time.Second}, fp)
607				if err == nil {
608					t.Fatalf("run returned no error, result %+v", res)
609				}
610				for _, w := range tc.wantIs {
611					if !errors.Is(err, w) {
612						t.Errorf("error %v does not wrap %v", err, w)
613					}
614				}
615				for _, w := range tc.wantNot {
616					if errors.Is(err, w) {
617						t.Errorf("error %v wraps %v, want it untouched", err, w)
618					}
619				}
620				if len(res.Hops) != 0 || res.Duration != 0 || res.Target.IsValid() {
621					t.Errorf("Result = %+v, want the zero Result", res)
622				}
623				if got := fp.sends.Load(); got != 0 {
624					t.Errorf("%d probes sent after an open failure, want none", got)
625				}
626				if got := fp.awaits.Load(); got != 0 {
627					t.Errorf("%d awaits after an open failure, want none", got)
628				}
629				if got := fp.openOK.Load(); got != tc.wantOpen {
630					t.Errorf("%d connections opened, want %d before the failure", got, tc.wantOpen)
631				}
632				assertBalanced(t, fp)
633			})
634		}
635	}
