696		}
697		if h := res.Hops[1]; h.Kind != HopError || !errors.Is(h.Err, recvErr) {
698			t.Errorf("Hops[1] = %+v, want HopError wrapping the await error", h)
699		}
700		if h := res.Hops[2]; h.Kind != HopError {
701			t.Errorf("Hops[2].Kind = %v, want error (reply not from ICMP)", h.Kind)
702		}
703		if h := res.Hops[3]; h.Kind != HopTarget {
704			t.Errorf("Hops[3].Kind = %v, want target", h.Kind)
705		}
706		assertBalanced(t, fp)
707	}
708

